 * Description  :
 * Create Date  :	2026-07-29
 ************************************************************************************/

scwin.gDepCd = $c.session.getUserInfo("depCd"); // 부서코드

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 조회조건·상태값 기본 설정.
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    $c.date.compareFromToDate(cal_sDate, cal_eDate);
    scwin.setCode();
    $c.cm.searchIsurCode(ibx_isurCd, ibx_comNm);

    // 해당 그룹 안의 컴포넌트에서 엔터키가 발생하면 해당 컴포넌트의 값을 DataCollection에 저장하고 objFunc 함수를 실행한다.
    $c.win.setEnterKeyEvent(tbl_search, scwin.btn_Search_onclick);
}

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_List_oncelldblclick
 * @description 목록 더블클릭
 * @param {Number} row 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_oncelldblclick = function (row, columnIndex, colid) {
    try {
        scwin.gAcptNo = dlt_selectListRes.getCellData(row, "acptNo");
        if (colid === "formKorNm") {
            $c.stf.openDisclViewer(scwin.gAcptNo, "R");
        } else if (colid === "comAbbrv") {
            scwin.fileAdd(scwin.gAcptNo);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @name btn_comNm_onclick
 * @description 회사코드(명) 조회 팝업
 * @returns {void}
 * @hidden N
 */
scwin.btn_comNm_onclick = function() {
    try {
        $c.cm.isurcdSearch(ibx_isurCd, ibx_comNm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.btn_comNm_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 조회 버튼 — 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (!await $c.validate.isValidDate(cal_sDate.getValue(), format = "YYYYMMDD")) {
            await $c.win.alert($c.data.getMessage("com_date_compare_0014"));
            cal_sDate.focus();
            return;
        }

        if (!await $c.validate.isValidDate(cal_eDate.getValue(), format = "YYYYMMDD")) {
            await $c.win.alert($c.data.getMessage("com_date_compare_0014"));
            cal_eDate.focus();
            return;
        }

        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05239.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 엑셀다운로드 버튼 — 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        scwin.excelDown();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 콜백(레거시 Gauce 이벤트 — 현재 통신 오류 알림은 $c.sbm 공통이 담당)
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadError = function() {
    try {
        $c.win.alert(dts_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트 — 순차 스타일에서는 await 뒤에서 호출)
 * @param {*} rowcount rowcount
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name ibx_isurCd_onkeyup
 * @description ibx_isurCd 키 입력 해제 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.ibx_isurCd_onkeyup = function() {
    try {
        if (ibx_isurCd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.comIsurNm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.ibx_isurCd_onkeyup" });
    }
};

/**
 * @method
 * @name ibx_isurCd_onfocus
 * @description ibx_isurCd 포커스 진입 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.ibx_isurCd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.ibx_isurCd_onfocus" });
    }
};

/**
 * @method
 * @name ibx_isurCd_onblur
 * @description ibx_isurCd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.ibx_isurCd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (ibx_isurCd.getValue() === "") {
            ibx_comNm.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.ibx_isurCd_onblur" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd_com_isur 키 입력 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.comConfirmSet();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 — 선택 행 처리
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.comConfirmSet();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd_com_isur 포커스 진입 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 — 입력값 검증·포맷
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name sbx_periodTp_onviewchange
 * @description 기간선택 selectBox 일자 세팅
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbx_periodTp_onviewchange = function (info) {
    try {
        let vTp = sbx_periodTp.getValue();
        $c.stf.setFromToDate(vTp, cal_sDate, cal_eDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.sbx_periodTp_onviewchange" });
    }
};

