/**
 * @method
 * @name btn_Close_onclick
 * @description 닫기 버튼
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    // await $c.win.closePopup();
};

/**
 * @method
 * @name sbx_teamList_onchange
 * @description 담당팀 변경시 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.sbx_teamList_onchange = function (info) {
    try {
        dlt_empnoDepcodeRes_sub.removeAll();

        if(info.newValue === "all") {
            dlt_empnoDepcodeRes_sub.setJSON(dlt_empnoDepcodeRes.getAllJSON());
        } else {
            let allData = dlt_empnoDepcodeRes.getAllJSON();
            let filterData = allData.filter(function(row) {
                return row.depCd === info.newValue;
            });
            dlt_empnoDepcodeRes_sub.setJSON(filterData);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239.sbx_teamList_onchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 코드 값을 화면에 설정한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    let vCurDate = $c.date.getServerDateTime();
    let vCurMonth = $c.date.addMonth(vCurDate, -2);
    cal_sDate.setValue(vCurMonth);
    cal_eDate.setValue(vCurDate);
    $c.stf.comboCbDataSetPeriod(sbx_periodTp);

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    const sbmOptions3 = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dma_depReq.set("depCd", scwin.gDepCd);
    const sbmOptions = {
        id: "sbm_depupcode",
        action: "/api/listing/common/code/depupcode",
        method: "get",
        ref : "dma_depReq",
        target : "dlt_depupcodeRes=body",
        isProcessMsg : true
    };
    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_depupcode_submitdone(sbmRtn);

};

/**
 * @method
 * @name sbm_depupcode_submitdone
 * @description 팀 리스트 조회 완료
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_depupcode_submitdone = async function() {
    // dlt_depupcodeRes.insertRow(0);
    // dlt_depupcodeRes.setCellData(0, "text", "전체");

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions3 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    sbx_teamList.setValue(scwin.gDepCd);

    const sbmOptions = {
        id: "sbm_empnoDepcode",
        action: "/api/listing/common/code/empno-depcode",
        method: "get",
        ref : "dma_depReq",
        target : "dlt_empnoDepcodeRes=body",
        isProcessMsg : true
    };
    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_empnoDepcode_submitdone(sbmRtn);
}

/**
 * @method
 * @name sbm_empnoDepcode_submitdone
 * @description 담당자 리스트 완료
 * @returns {void}
 * @hidden N
 */
scwin.sbm_empnoDepcode_submitdone = function() {
    // dlt_empnoDepcodeRes.insertRow(0);
    // dlt_empnoDepcodeRes.setCellData(0, "text", "전체");
    dlt_empnoDepcodeRes_sub.setJSON(dlt_empnoDepcodeRes.getAllJSON());
    scwin.listSync();
}

/**
 * @method
 * @name listSync
 * @description 목록을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions3 = {
        id : "sbm_dts_List",
        action : "/ListedReceive.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dma_selectListReq.set("acptSdate", cal_sDate.getValue());
    dma_selectListReq.set("acptEdate", cal_eDate.getValue());
    dma_selectListReq.set("isurCd", ibx_isurCd.getValue());
    dma_selectListReq.set("depCd", sbx_teamList.getValue() === "all" ? "" : sbx_teamList.getValue());
    dma_selectListReq.set("empNo", sbx_empList.getValue() === "all" ? "" : sbx_empList.getValue());
    const sbmOptions = {
        id: "sbm_selectList",
        action: "/api/listing/lstproc/kospi-appl-attach/select-list",
        method: "get",
        ref : "dma_selectListReq",
        target : "dlt_selectListRes=body",
        isProcessMsg : true
    };
    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_selectList_submitdone(sbmRtn);
};

/**
 * @method
 * @name sbm_selectList_submitdone
 * @description 목록 조회 완료
 * @returns {void}
 * @hidden N
 */
scwin.sbm_selectList_submitdone = function() {
    tbx_totCnt.setValue(dlt_selectListRes.getRowCount());
}

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name excelDown
 * @description 함수명 : fn_ExcelDown() 설명 : 정보를 excel로 다운 받는다
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (dlt_selectListRes.getRowCount() > 0) {
        // 엑셀 로그
        // $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "상장신청서 첨부파일 조회", type: "3"});
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name fileAdd
 * @description 첨부파일목록 팝업
 * @param {String} acptNo 식별자
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileAdd = async function(acptNo) {
    // let url = "/lstproc/ULDSTF05239_FILE.gfm?ACPT_NO=" + scwin.gAcptNo;
    // await $c.win.openPopup 함수로 전환 필요 : await $c.frame.CreateDialogFrame("", url, "첨부파일목록", 100, 100, 600, 300, "window");

    const data = {
        acptNo: acptNo,
    };
    const opts = {
        id: "ULDSTF05239_FILE",
        popupName: "첨부파일목록",
        width: 600,
        height: 400,
        frameModal: "top",
        type: "pageFramePopup",
    };
    await $c.win.openPopup("/ui/lst/lstproc/ULDSTF05239_FILE.xml", opts, data);
};

/**
 * @method
 * @name dateCustomFormatter
 * @description date format
 * @param {*} data 셀 값(원본 데이터)
 * @param {String} formattedData 표시 형식 문자열
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.dateCustomFormatter = function (data, formattedData, rowIndex, columnIndex) {
    if(data.length === 14) {
        return $c.date.formatDateTime(data, "yyyy-MM-dd HH:mm:ss");
    }
    return data;
};
